// END GENERATED OFFLINE DIGESTS
async function verified(asset,response){
  if(!response?.ok)return false;
  const name=asset.split('?')[0],expected=ASSET_DIGESTS[name];
  if(!expected)return false;
  let bytes=await response.clone().arrayBuffer();
  if(/\.(?:html?|js|css|svg|json|webmanifest)$/i.test(name)){
    const text=new TextDecoder().decode(bytes).replace(/^\uFEFF/,'').replace(/\r\n/g,'\n');
    bytes=new TextEncoder().encode(text);
  }
  const digest=await crypto.subtle.digest('SHA-256',bytes);
  const actual=Array.from(new Uint8Array(digest),byte=>byte.toString(16).padStart(2,'0')).join('');
  return actual===expected;
}
async function storeAsset(asset,cache,previous){
  const request=new Request(new URL(asset,self.registration.scope));
  // Only reuse a previous Beta response when its contents match this release.
  for(const old of previous){
    try{
      const response=await old.match(request);
      if(await verified(asset,response)){await cache.put(request,response);return;}
    }catch{/* A missing or unreadable old response is downloaded below. */}
  }
  for(let attempt=0;;attempt++){
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);
    try{
      const url=new URL(request.url);
      if(attempt)url.searchParams.set('sana_update',CACHE);
      const response=await fetch(url.href,{cache:'reload',signal:controller.signal});
      if(!await verified(asset,response))throw Error('The downloaded file does not match this release');
      await cache.put(request,response);return;
    }catch(error){if(attempt===2)throw error;}
    finally{clearTimeout(timer);}
    await new Promise(resolve=>setTimeout(resolve,500*(attempt+1)));
  }
}
self.addEventListener('install',event=>{
  event.waitUntil((async()=>{
    const cache=await caches.open(CACHE);
    try{
      const names=(await caches.keys()).filter(name=>name.startsWith(PREFIX)&&name!==CACHE).reverse();
      const previous=await Promise.all(names.map(name=>caches.open(name)));
      // Copy verified unchanged files locally; fetch only missing or changed files.
      for(let offset=0;offset<ASSETS.length;offset+=4){
        const batch=ASSETS.slice(offset,offset+4);
        await Promise.all(batch.map(asset=>storeAsset(asset,cache,previous)));
      }
    }catch(error){
      await caches.delete(CACHE);
      throw error;
    }
    await self.skipWaiting();
  })());
});
self.addEventListener('activate',event=>{
  event.waitUntil((async()=>{
    const keys=await caches.keys();
    await Promise.all(keys.filter(key=>key.startsWith(PREFIX)&&key!==CACHE).map(key=>caches.delete(key)));
    await self.clients.claim();
  })());
});
self.addEventListener('message',event=>{
  if(event.data?.type!=='OFFLINE_STATUS'||!event.ports[0])return;
  event.waitUntil((async()=>{
    try{
      const cache=await caches.open(CACHE);
      const ready=(await Promise.all(ASSETS.map(path=>cache.match(path)))).every(Boolean);
      event.ports[0].postMessage({ready,version:CACHE});
    }catch{event.ports[0].postMessage({ready:false});}
  })());
});
self.addEventListener('fetch',event=>{
  const url=new URL(event.request.url),scope=new URL(self.registration.scope);
  if(event.request.method!=='GET'||url.origin!==scope.origin||!url.pathname.startsWith(scope.pathname))return;
  event.respondWith((async()=>{
    const cache=await caches.open(CACHE);
    if(event.request.mode==='navigate'&&url.pathname===scope.pathname){
      const welcome=await cache.match('./index.html');if(welcome)return welcome;
    }
    const cached=await cache.match(event.request,{ignoreSearch:event.request.mode==='navigate'});
    return cached||fetch(event.request);
  })());
});
